def remote_run(payload, checksums, expected, stage_name="puzzle"):
    import base64
    import hashlib
    import json
    import os
    from pathlib import Path
    import subprocess
    import sys
    import tempfile
    import traceback
    import zlib

    out = Path("/kaggle/working")
    scratch = Path("/kaggle/temp")
    out.mkdir(parents=True, exist_ok=True)
    scratch.mkdir(parents=True, exist_ok=True)
    for option in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS"):
        os.environ[option] = "4"
    manifest = {"input_sha256": checksums, "status": "starting"}
    try:
        import torch
        torch.set_num_threads(4)
        if not torch.cuda.is_available():
            raise RuntimeError(f"The {stage_name} evaluation requires CUDA")
        manifest.update(device=torch.cuda.get_device_name(0), available_devices=torch.cuda.device_count(),
                        pytorch=str(torch.__version__), cuda=torch.version.cuda)
        with tempfile.TemporaryDirectory(dir=scratch) as name:
            stage = Path(name)
            for rel, encoded in payload.items():
                data = zlib.decompress(base64.b64decode(encoded, validate=True))
                if hashlib.sha256(data).hexdigest() != checksums[rel]:
                    raise ValueError(f"Embedded checksum mismatch for {rel}")
                dest = stage / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(data)
            print(f"Running on {manifest['device']} with {len(checksums)} frozen inputs", flush=True)
            command = [sys.executable, "-u", str(stage / "experiment.py"), "gpu"]
            with (out / f"{stage_name}-driver.log").open("w", encoding="utf-8") as log:
                with subprocess.Popen(command, cwd=out, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                      text=True, encoding="utf-8", errors="replace") as proc:
                    for line in proc.stdout:
                        print(line, end="", flush=True)
                        log.write(line)
                        log.flush()
                    rc = proc.wait()
                if rc:
                    raise subprocess.CalledProcessError(rc, command)
        hashes = {}
        for name in expected:
            data = (out / name).read_bytes()
            if name.endswith(".json"):
                json.loads(data)
            hashes[name] = hashlib.sha256(data).hexdigest()
        manifest.update(status="complete", output_sha256=hashes)
    except BaseException:
        manifest.update(status="failed", error=traceback.format_exc())
        raise
    finally:
        (out / f"{stage_name}-runtime.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")

remote_run({'experiment.py': '', 'protocol.json': '', 'checks.json': '', 'isotopes.py': '', 'calendar_round.py': '', 'arm.py': '', 'cases.json.gz': '', 'weights.npz': '', 'freeze.json': ''}, {'experiment.py': 'cbb8669d0586f2806a418a113a7bd3d602f7af6b6636d757928afd156d971bf6', 'protocol.json': 'cb6ec26f6395ea4783ae666f19b0c457886e4e2ec66fd94e7ddcf63d1b717736', 'checks.json': '3401d6052a62d11bcad0a2c7e12933d013c96078f87cdcea7d79340c1182a3e4', 'isotopes.py': '105497332369e0ff7a643aef821a8f9fbf1f2735c4a8725a0cb10ac50d687a80', 'calendar_round.py': 'c11a5515aeeb97af238fb6597e4618b1dcf377a33e4485a895e461a3ccec1694', 'arm.py': 'aca1c922c164bf961c524a267090005c5805e8424fc075e3b61e20da639c4a07', 'cases.json.gz': 'e8e4e40b126e320737a182837337f5fda231cc607d73c95d44e6343b6cfd50a9', 'weights.npz': 'd55e60b699f92944d294d31c74c9c829a671dfb73c819e7d5a09a473ede3b1a1', 'freeze.json': 'b75f971bd684f368f3d55da6ef45303b77154e7731120e4aadd3220c709690f4'}, ['prism-results.json', 'prism-predictions.npz'], 'prism')
